mapper.select:
        select
        orders.*,
        subject.subject_name,
        users.nick_name,
        users.avatar,
        teacher.name,
        types.type_name,
        teacher.head_img
        from orders orders
        left join subject subject on orders.subject_id = subject.id
		left join types types on orders.type_id = types.id
		left join users users on orders.user_id = users.id
		left join teacher teacher on orders.teacher_id = teacher.id

            and orders.id = #{id}
            and orders.user_id = #{userId}
            and orders.teacher_id = #{teacherId}
            and orders.student_time = #{studentTime}
            and orders.address = #{address}
            and orders.subject_id = #{subjectId}
            and orders.status = #{status}
            and orders.remark = #{remark}
            and orders.create_time = #{createTime}
            and orders.type_id = #{typeId}
            and subject.subject_name like concat('%',#{subjectName},'%')
            and users.nick_name like concat('%',#{nickName},'%')
            and users.avatar = #{avatar}
            and teacher.name like concat('%',#{name},'%')
            and teacher.head_img = #{headImg}


            limit #{current},#{pageSize}

        select count(*) from orders orders
        left join subject subject on orders.subject_id = subject.id
		left join types types on orders.type_id = types.id
		left join users users on orders.user_id = users.id
		left join teacher teacher on orders.teacher_id = teacher.id

            and orders.id = #{id}
            and orders.user_id = #{userId}
            and orders.teacher_id = #{teacherId}
            and orders.student_time = #{studentTime}
            and orders.address = #{address}
            and orders.subject_id = #{subjectId}
            and orders.status = #{status}
            and orders.remark = #{remark}
            and orders.create_time = #{createTime}
            and orders.type_id = #{typeId}
            and subject.subject_name like concat('%',#{subjectName},'%')
            and users.nick_name like concat('%',#{nickName},'%')
            and users.avatar = #{avatar}
            and teacher.name like concat('%',#{name},'%')
            and teacher.head_img = #{headImg}
